-- Each part: the tarball component and the object subdirectory it goes in.
CommonsLang_Rust_Std.PARTS = { { "rust-std", "" } }

function CommonsLang_Rust_Std.form_output_id()
  return string.format("%s.Form@%s", CommonsLang_Rust_Std.id_module, CommonsLang_Rust_Std.id_version)
end

-- One CommonsBase_Std.Extract.F_Untar per part. Each untar is its own object
-- (Release.Agnostic), so its module id names the part and the slot.
function CommonsLang_Rust_Std.form_values(slot)
  local triple = assert(CommonsLang_Rust_Std.TRIPLES[slot], "unsupported slot: " .. slot)
  local private = {}
  local outpaths = {}
  local i = 1
  local part = CommonsLang_Rust_Std.PARTS[1]
  while part do
    local comp = part[1]
    local sub = part[2]
    local paths = CommonsLang_Rust_Std.PATHS[slot .. "|" .. comp]
    local dir = "${SLOT." .. slot .. "}"
    local prefix = ""
    if sub ~= "" then
      dir = dir .. "/" .. sub
      prefix = sub .. "/"
    end
    local modname = comp
    if comp == "rust-std" then modname = "Std" end
    if comp == "rustc" then modname = "Rustc" end
    if comp == "cargo" then modname = "Cargo" end
    local cmd = string.format(
      "run-function CommonsBase_Std.Extract.F_Untar@0.3.0 -d %s modver=CommonsLang_Rust.%s.Untar.%s.%s@%s tarmodver=%s tarassetpath=%s-%s-%s.tar.gz",
      dir, "Std", modname, string.sub(slot, 9), CommonsLang_Rust_Std.id_version,
      CommonsLang_Rust_Std.bundle, comp, CommonsLang_Rust_Std.id_version, triple)
    local j = 1
    local p = paths[1]
    while p do
      cmd = cmd .. " paths[]=" .. p
      table.insert(outpaths, prefix .. p)
      j = j + 1
      p = paths[j]
    end
    table.insert(private, cmd)
    i = i + 1
    part = CommonsLang_Rust_Std.PARTS[i]
  end
  return { private = private }, { assets = { { slots = { slot }, paths = outpaths } } }
end

function rules.Files(command, request)
  if command == "declareoutput" then
    local slot = assert(request.user.slot, "please provide `slot=SLOT`")
    return { declareoutput = { return_objects = {
      id = CommonsLang_Rust_Std.form_output_id(),
      slots = CommonsLang_Rust_Std.SLOTS,
      execution_slot = slot } } }
  elseif command == "submit" then
    local slot = assert(request.user.slot, "please provide `slot=SLOT`")
    local precommands, outputs = CommonsLang_Rust_Std.form_values(slot)
    return { submit = { values = { schema_version = { major = 1, minor = 0 },
      forms = { { id = request.submit.outputid, precommands = precommands, outputs = outputs } } } } }
  end
end

return M
